list.definition:
SELECT COLUMN_NAME
FROM INFORMATION_SCHEMA.COLUMNS
WHERE TABLE_NAME = 'tbl_' + ${device:singlequote} + '_' + ${message:singlequote}
AND COLUMN_NAME <> 't'
ORDER BY ORDINAL_POSITION;

list.query:
