list.definition:
WITH SplitColumns AS (
    SELECT TRIM(value) AS ColumnName
    FROM STRING_SPLIT('${signal:csv}', ',')
)
SELECT STRING_AGG(CONCAT(
    'AVG(', ColumnName, ') AS AVG_', ColumnName, ', ',
    'MIN(', ColumnName, ') AS MIN_', ColumnName, ', ',
    'MAX(', ColumnName, ') AS MAX_', ColumnName
), ', ')
FROM SplitColumns;

